#!/usr/bin/env bash
# CivicLearn render service - v1.3.0 to v1.4.0.
#   template.html: hide the explanation card when there is no explanation; auto-shrink long ones.
#   server.js:     version bump.
# Backs up, verifies every file by sha256 before installing, and rolls back if the rebuild is unhealthy.
set -euo pipefail
APP=/opt/render
[ -d $APP/app ] || { echo "render service not installed (no $APP/app)"; exit 1; }
STAMP=$(date +%Y%m%d-%H%M%S)
cp -a $APP/app $APP/app.bak-$STAMP
docker tag civiclearn-render civiclearn-render:prev 2>/dev/null || true
echo "== backup: $APP/app.bak-$STAMP, previous image tagged civiclearn-render:prev"

python3 - <<'PYEOF'
import hashlib, json, pathlib, sys
APP = pathlib.Path("/opt/render/app")
EDITS = json.loads('{"server.js": [["const EL_MODEL = process.env.ELEVENLABS_MODEL || \'eleven_multilingual_v2\';\\nconst KEEP_DAYS = +(process.env.KEEP_DAYS || 14);\\nconst VERSION = \'1.3.0\';\\nif (!TOKEN) { console.error(\'RENDER_TOKEN is required\'); process.exit(1); }\\nfs.mkdirSync(OUT, { recursive: true });\\n", "const EL_MODEL = process.env.ELEVENLABS_MODEL || \'eleven_multilingual_v2\';\\nconst KEEP_DAYS = +(process.env.KEEP_DAYS || 14);\\nconst VERSION = \'1.4.0\';\\nif (!TOKEN) { console.error(\'RENDER_TOKEN is required\'); process.exit(1); }\\nfs.mkdirSync(OUT, { recursive: true });\\n"]], "template.html": [["      background: rgba(255,255,255,.14); border: 2px solid rgba(255,255,255,.26); color: rgba(255,255,255,.92); }\\n\\n  .qcard { position: absolute; top: 610px; left: 72px; right: 72px; background: #fff; color: #0b1d3a; border-radius: 40px; padding: 52px 56px; box-shadow: 0 30px 80px rgba(0,0,0,.35); }\\n  .qcard .q { font-size: 52px; font-weight: 700; line-height: 1.22; }\\n", "      background: rgba(255,255,255,.14); border: 2px solid rgba(255,255,255,.26); color: rgba(255,255,255,.92); }\\n\\n  /* optional picture above the question \\u2014 inline SVG or a data: image, never a remote file */\\n  .visual { position: absolute; left: 72px; right: 72px; display: none; text-align: center; }\\n  .visual .box { display: inline-flex; align-items: center; justify-content: center;\\n      width: 300px; height: 235px; border-radius: 40px; background: rgba(255,255,255,.14);\\n      border: 3px solid rgba(255,255,255,.26); font-size: 150px; line-height: 1; }\\n  .qcard { position: absolute; top: 610px; left: 72px; right: 72px; background: #fff; color: #0b1d3a; border-radius: 40px; padding: 52px 56px; box-shadow: 0 30px 80px rgba(0,0,0,.35); }\\n  .qcard .q { font-size: 52px; font-weight: 700; line-height: 1.22; }\\n"], ["  <div class=\\"hook\\" id=\\"hook\\">Klarar du <em>provet</em>?</div>\\n  <div class=\\"kicker\\" id=\\"kicker\\"></div>\\n  <div class=\\"qcard\\" id=\\"qcard\\"><div class=\\"q\\" id=\\"q\\"></div></div>\\n  <div class=\\"opts\\" id=\\"opts\\"></div>\\n", "  <div class=\\"hook\\" id=\\"hook\\">Klarar du <em>provet</em>?</div>\\n  <div class=\\"kicker\\" id=\\"kicker\\"></div>\\n  <div class=\\"visual\\" id=\\"visual\\"></div>\\n  <div class=\\"qcard\\" id=\\"qcard\\"><div class=\\"q\\" id=\\"q\\"></div></div>\\n  <div class=\\"opts\\" id=\\"opts\\"></div>\\n"], ["      $(\'kicker\').style.display = \'none\';\\n    }\\n    $(\'qcard\').style.top = cardTop + \'px\';\\n    // layout: place options under the question card, timer/explain under options\\n", "      $(\'kicker\').style.display = \'none\';\\n    }\\n    if (spec.visual) {\\n      $(\'visual\').innerHTML = \'<div class=\\"box\\">\' + spec.visual + \'</div>\';\\n      $(\'visual\').style.display = \'block\';\\n      $(\'visual\').style.top = cardTop + \'px\';\\n      cardTop = $(\'visual\').getBoundingClientRect().bottom + 36;\\n    } else {\\n      $(\'visual\').style.display = \'none\';\\n    }\\n    $(\'qcard\').style.top = cardTop + \'px\';\\n    // layout: place options under the question card, timer/explain under options\\n"]], "render.js": [["}\\n\\nfunction voiceLines(spec) {\\n  const prefix = spec.answer_prefix || \'R\\u00e4tt svar:\';\\n", "}\\n\\nasync function downloadTo(url, dst) {\\n  const r = await fetch(url);\\n  if (!r.ok) throw new Error(`fetch ${url}: ${r.status}`);\\n  fs.writeFileSync(dst, Buffer.from(await r.arrayBuffer()));\\n  return dst;\\n}\\n\\nfunction voiceLines(spec) {\\n  const prefix = spec.answer_prefix || \'R\\u00e4tt svar:\';\\n"], ["  if (ownBrowser) browser = await chromium.launch();\\n  try {\\n    const lines = voiceLines(spec);\\n    const qWav = path.join(dir, \'q.wav\'), eWav = path.join(dir, \'e.wav\');\\n    log(\'audio\');\\n    const dQ = audio.q ? toWav(audio.q, qWav) : piper(lines.q, qWav);\\n    const dE = audio.e ? toWav(audio.e, eWav) : piper(lines.e, eWav);\\n\\n    const T = {};\\n    T.qIn = 0.45; T.optIn = 0.95;\\n    T.voiceQ = 0.9;\\n    T.cd = T.voiceQ + dQ + 0.35;          // countdown starts after the question is read\\n    T.reveal = T.cd + (spec.countdown || 4);\\n    T.voiceE = T.reveal + 0.5;\\n    T.cta = T.voiceE + dE + 0.9;\\n    T.end = T.cta + (spec.ctaSeconds || 3.2);\\n    const nFrames = Math.ceil(T.end * FPS);\\n", "  if (ownBrowser) browser = await chromium.launch();\\n  try {\\n    const silent = !!spec.silent;         // no narration at all (short Luxembourgish snippets)\\n    const lines = voiceLines(spec);\\n    const qWav = path.join(dir, \'q.wav\'), eWav = path.join(dir, \'e.wav\');\\n    let dQ, dE;\\n    if (silent) {\\n      // Nothing is spoken, so the pacing has to come from how long the text takes to READ.\\n      // ~22 chars/second, clamped, and the reveal simply holds for a beat.\\n      log(\'silent\');\\n      dQ = Math.min(4.0, Math.max(1.6, 0.9 + String(spec.question || \'\').length / 22));\\n      dE = spec.explain ? Math.min(6.0, Math.max(2.0, 1.0 + spec.explain.length / 22)) : 2.4;\\n    } else {\\n      log(\'audio\');\\n      dQ = audio.q ? toWav(audio.q, qWav) : piper(lines.q, qWav);\\n      dE = audio.e ? toWav(audio.e, eWav) : piper(lines.e, eWav);\\n    }\\n\\n    const T = {};\\n    T.qIn = 0.45; T.optIn = 0.95;\\n    T.voiceQ = silent ? 0 : 0.9;\\n    T.cd = (silent ? 0.6 : T.voiceQ) + dQ + 0.35;   // countdown starts once the question can be read\\n    T.reveal = T.cd + (spec.countdown || 4);\\n    T.voiceE = T.reveal + (silent ? 0 : 0.5);\\n    T.cta = T.voiceE + dE + (silent ? 0.4 : 0.9);\\n    T.end = T.cta + (spec.ctaSeconds || 3.2);\\n    const nFrames = Math.ceil(T.end * FPS);\\n"], ["    await page.close();\\n\\n    const tick = path.join(dir, \'tick.wav\'), ding = path.join(dir, \'ding.wav\');\\n    tone(tick, 880, 0.09, 0.25);\\n", "    await page.close();\\n\\n    let music = null;\\n    if (spec.music) {\\n      try {\\n        music = path.join(dir, \'bed\' + (path.extname(new URL(spec.music).pathname) || \'.mp3\'));\\n        await downloadTo(spec.music, music);\\n      } catch (e) { log(\'music failed: \' + e.message); music = null; }   // a missing bed must not fail the video\\n    }\\n    const tick = path.join(dir, \'tick.wav\'), ding = path.join(dir, \'ding.wav\');\\n    tone(tick, 880, 0.09, 0.25);\\n"], ["    const ms = s => Math.round(s * 1000);\\n    const nTicks = Math.max(0, Math.floor(T.reveal - T.cd) - 1);\\n    const inputs = [\'-framerate\', String(FPS), \'-i\', path.join(dir, \'f%05d.jpg\'), \'-i\', qWav, \'-i\', eWav, \'-i\', ding];\\n    const parts = [`[1]adelay=${ms(T.voiceQ)}|${ms(T.voiceQ)}[vq]`, `[2]adelay=${ms(T.voiceE)}|${ms(T.voiceE)}[ve]`, `[3]adelay=${ms(T.reveal)}|${ms(T.reveal)}[dg]`];\\n    const labels = [\'[vq]\', \'[ve]\', \'[dg]\'];\\n    for (let i = 1; i <= nTicks; i++) {\\n      inputs.push(\'-i\', tick);\\n      parts.push(`[${3 + i}]adelay=${ms(T.cd + i)}|${ms(T.cd + i)}[t${i}]`);\\n      labels.push(`[t${i}]`);\\n    }\\n    parts.push(`${labels.join(\'\')}amix=inputs=${labels.length}:normalize=0,apad[a]`);\\n", "    const ms = s => Math.round(s * 1000);\\n    const nTicks = Math.max(0, Math.floor(T.reveal - T.cd) - 1);\\n    // ffmpeg input indices must be counted explicitly: the video input spans four argv entries\\n    // (\'-framerate\', n, \'-i\', path) and so does the music input (\'-ss\', off, \'-i\', path).\\n    const inputs = [\'-framerate\', String(FPS), \'-i\', path.join(dir, \'f%05d.jpg\')];\\n    const parts = [], labels = [];\\n    let nIn = 1;                                   // input 0 is the frame sequence\\n    const addInput = (...argv) => { inputs.push(...argv); return nIn++; };\\n    if (!silent) {\\n      const iq = addInput(\'-i\', qWav), ie = addInput(\'-i\', eWav);\\n      parts.push(`[${iq}]adelay=${ms(T.voiceQ)}|${ms(T.voiceQ)}[vq]`);\\n      parts.push(`[${ie}]adelay=${ms(T.voiceE)}|${ms(T.voiceE)}[ve]`);\\n      labels.push(\'[vq]\', \'[ve]\');\\n    }\\n    const iDing = addInput(\'-i\', ding);\\n    parts.push(`[${iDing}]adelay=${ms(T.reveal)}|${ms(T.reveal)}[dg]`);\\n    labels.push(\'[dg]\');\\n    for (let i = 1; i <= nTicks; i++) {\\n      const k = addInput(\'-i\', tick);\\n      parts.push(`[${k}]adelay=${ms(T.cd + i)}|${ms(T.cd + i)}[t${i}]`);\\n      labels.push(`[t${i}]`);\\n    }\\n    // optional music bed: started at an offset so consecutive videos do not open on the same bars\\n    if (music) {\\n      const off = (spec.music_offset != null) ? spec.music_offset : Math.floor(Math.random() * 60);\\n      const k = addInput(\'-ss\', String(off), \'-i\', music);\\n      parts.push(`[${k}]atrim=0:${T.end.toFixed(2)},volume=${(spec.music_gain || 1).toFixed(2)},` +\\n                 `afade=t=in:st=0:d=0.4,afade=t=out:st=${Math.max(0, T.end - 1.0).toFixed(2)}:d=1.0[bed]`);\\n      labels.push(\'[bed]\');\\n    }\\n    parts.push(`${labels.join(\'\')}amix=inputs=${labels.length}:normalize=0,apad[a]`);\\n"], ["    execFileSync(\'ffmpeg\', [\'-y\', \'-v\', \'error\', ...inputs, \'-filter_complex\', parts.join(\';\'), \'-map\', \'0:v\', \'-map\', \'[a]\',\\n      \'-c:v\', \'libx264\', \'-preset\', \'medium\', \'-crf\', \'20\', \'-pix_fmt\', \'yuv420p\', \'-r\', String(FPS),\\n      \'-c:a\', \'aac\', \'-b:a\', \'160k\', \'-t\', T.end.toFixed(3), \'-movflags\', \'+faststart\', outFile]);\\n    return { seconds: +T.end.toFixed(1), timeline: T };\\n  } finally {\\n", "    execFileSync(\'ffmpeg\', [\'-y\', \'-v\', \'error\', ...inputs, \'-filter_complex\', parts.join(\';\'), \'-map\', \'0:v\', \'-map\', \'[a]\',\\n      \'-c:v\', \'libx264\', \'-preset\', \'medium\', \'-crf\', \'20\', \'-pix_fmt\', \'yuv420p\', \'-r\', String(FPS),\\n      \'-c:a\', \'aac\', \'-b:a\', \'160k\', \'-ac\', \'2\', \'-t\', T.end.toFixed(3), \'-movflags\', \'+faststart\', outFile]);\\n    return { seconds: +T.end.toFixed(1), timeline: T };\\n  } finally {\\n"]]}')
WANT = json.loads('{"server.js": "7edabcb0d65ba9d2ace60a53e9a9e9755d7fe63e1218b6d2f0608d93e05446c1", "template.html": "62bd0ef8073a663719d72a2b5177737f977af116a96001e3d5d9e24d4d4b2eb8", "render.js": "c206c461269ece258d84bb98eb8cbb5da05340f85fab8ba4f01a7231e040a96b"}')
for name, pairs in EDITS.items():
    t = (APP / name).read_text()
    for old, new in pairs:
        if t.count(new) == 1:
            continue                       # already patched (check `new` first: a pure insertion
                                           # leaves the old anchor text intact inside the new text)
        if t.count(old) != 1:
            sys.exit("!! " + name + ": anchor not found - box is not at the expected v1.3.0, stop and tell Claude")
        t = t.replace(old, new)
    (APP / (name + ".new")).write_text(t)
for name, h in WANT.items():
    p = APP / (name + ".new")
    if not p.exists():
        sys.exit("!! missing " + name + ".new - stop and tell Claude")
    got = hashlib.sha256(p.read_bytes()).hexdigest()
    if got != h:
        sys.exit("!! " + name + ": sha256 " + got + " != expected " + h + " - stop and tell Claude")
print("verified: " + ", ".join(sorted(WANT)))

PYEOF

for f in server.js template.html render.js; do mv $APP/app/$f.new $APP/app/$f; done
rm -f $APP/app/*.new
echo "== rebuilding image"
docker build -q -t civiclearn-render $APP/app >/dev/null
docker rm -f render >/dev/null 2>&1 || true
docker run -d --name render --restart unless-stopped -p 8080:8080 --env-file $APP/.env -v $APP/out:/app/out civiclearn-render >/dev/null
sleep 6
if curl -sf localhost:8080/health >/dev/null; then
  echo "Health: $(curl -s localhost:8080/health)"
  echo "OK - expect version 1.4.0 above"
else
  echo "!! new container is NOT healthy - rolling back to the previous image and files"
  docker rm -f render >/dev/null 2>&1 || true
  rm -rf $APP/app && cp -a $APP/app.bak-$STAMP $APP/app
  docker run -d --name render --restart unless-stopped -p 8080:8080 --env-file $APP/.env -v $APP/out:/app/out civiclearn-render:prev >/dev/null
  sleep 6
  echo "Rolled back. Health: $(curl -s localhost:8080/health)"
  echo "Tell Claude: rebuild was unhealthy, rolled back"
  exit 1
fi
